#!/usr/bin/env python3
"""Shipped Brightwake DOM, scripts, Canvas3D and delegated user events in Chromium.
Network navigation is restricted in this environment. This fixture supplies an explicit
asynchronous IndexedDB-shaped adapter, not native Safari persistence or live hosting.
No real child/fleet records are used. All downloadable files contain synthetic nicknames.
"""
import argparse,json,re,shutil
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('--out',type=Path,required=True);args=p.parse_args();root=args.root.resolve();out=args.out.resolve();out.mkdir(parents=True,exist_ok=True)
checks=[];errors=[];network=[]
def check(name,ok):
 checks.append({'name':name,'pass':bool(ok)});print(('PASS ' if ok else 'FAIL ')+name,flush=True)
 if not ok: raise AssertionError(name)
html=(root/'brightwake.html').read_text();html=re.sub(r'<script[^>]*>.*?</script>','',html,flags=re.S);html=re.sub(r'<meta http-equiv="Content-Security-Policy"[^>]*>','',html);html=re.sub(r'<link[^>]*>','',html)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 context=browser.new_context(viewport={'width':1194,'height':834},has_touch=True,accept_downloads=True)
 context.route('**/*',lambda r:(network.append(r.request.url),r.abort()))
 page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content(html);page.add_style_tag(content=(root/'brightwake.css').read_text());page.add_script_tag(content=(root/'BRIGHTWAKE_TEST_FIXTURE.js').read_text())
 # Prevent accidental reuse of old fleet localStorage. No app code is changed.
 page.add_script_tag(content="Object.defineProperty(window,'localStorage',{get(){throw new Error('Unrelated storage access is forbidden in test')},configurable:true});")
 for file in ['stormwake_three_vendor.js','brightwake_curriculum.js','brightwake_core.js','brightwake_store.js','brightwake_play.js','brightwake_scene.js','brightwake_app.js']:page.add_script_tag(content=(root/file).read_text())
 page.wait_for_selector('.home');page.wait_for_timeout(600)
 check('home is rendered without any learner creation or network send',page.locator('.activity-card').count()==4 and not network)
 check('full 3D diorama or explicit fallback is available',page.locator('#world canvas,#world svg').count()>0)
 page.locator('[data-act="new-learner"]').first.click();page.locator('[name="nickname"]').fill('Moon Fox');page.locator('#new-learner-form button[type="submit"]').click();page.wait_for_selector('.learner-pill')
 page.wait_for_timeout(150);data=page.evaluate('BrightwakeStore.list()');a=data[0]['id']
 check('first learner is saved and read back',data[0]['nickname']=='Moon Fox' and len(data)==1)
 page.locator('.learner-pill').click();page.locator('#modal [data-act="new-learner"]').click();page.locator('[name="nickname"]').fill('Star Owl');page.locator('[name="math-grade"]').select_option('9');page.locator('[name="word-grade"]').select_option('6');page.locator('[name="theme"]').select_option('night');page.locator('[data-avatar="owl"]').click();page.locator('#new-learner-form button[type="submit"]').click();page.wait_for_timeout(220)
 data=page.evaluate('BrightwakeStore.list()');b=next(p['id'] for p in data if p['nickname']=='Star Owl');beta_before=next(p for p in data if p['id']==b)
 check('second learner has separate subject starting points',beta_before['math']['cursor']==27 and beta_before['words']['level']==6)
 check('older learner can choose mature night appearance independently',page.locator('body.night').count()==1)
 page.locator('.learner-pill').click();page.locator(f'#modal [data-id="{a}"]').click();page.wait_for_timeout(100)
 check('switcher restores first learner and its world',page.locator('.profile-name').inner_text()=='Moon Fox' and page.locator('body.night').count()==0)
 page.screenshot(path=str(out/'brightwake-islands-ipad.png'),full_page=True)
 page.locator('.activity-card[data-act="math"]').click();count=page.locator('.visual .count-dot').count();page.locator(f'[data-number="{count}"]').click();page.locator('[data-act="check"]').click();page.wait_for_selector('[data-act="next"]')
 data=page.evaluate('BrightwakeStore.list()');alpha=next(p for p in data if p['id']==a);beta=next(p for p in data if p['id']==b)
 check('math answer saves only the selected learner',alpha['completed']==1 and beta==beta_before)
 check('one answer is not certified mastery',not alpha['math']['skills']['count']['ready'])
 page.screenshot(path=str(out/'brightwake-math-ipad.png'),full_page=True)
 page.locator('[data-act="next"]').click();page.locator('[data-act="hint"]').click();count=page.locator('.visual .count-dot').count();page.locator(f'[data-number="{count}"]').click();page.locator('[data-act="check"]').click();page.wait_for_selector('[data-act="next"]')
 alpha=page.evaluate('id=>BrightwakeStore.get(id)',a);check('supported practice does not add independent mastery credit',alpha['math']['skills']['count']['independent']==1)
 page.locator('[data-act="home"]').first.click();page.locator('.activity-card[data-act="words"]').click();page.locator('[data-act="peek"]').click();word=page.locator('#slots').inner_text();page.locator('[data-act="peek"]').click();page.locator('#word-answer').fill(word);page.locator('[data-act="check"]').click();page.wait_for_selector('[data-act="next"]')
 alpha=page.evaluate('id=>BrightwakeStore.get(id)',a);check('spelling progress separate from math and flagged supported after showing target',alpha['words']['skills']['words-0']['attempts']==1 and alpha['words']['skills']['words-0']['independent']==0)
 check('unrelated sibling still unchanged',page.evaluate('id=>BrightwakeStore.get(id)',b)==beta_before)
 page.locator('[data-act="home"]').first.click();page.locator('.activity-card[data-act="studio"]').click();page.locator('[data-shape="triangle"]').click();page.locator('[data-act="art-left"]').click();page.locator('[data-act="art-color"][data-color="#284c60"]').click();page.locator('[data-shape="heart"]').click();page.locator('[data-act="art-right"]').click();page.locator('#art-title').fill('Moon Fox’s pumpkin');page.locator('[data-act="save-art"]').click();page.wait_for_timeout(180)
 alpha=page.evaluate('id=>BrightwakeStore.get(id)',a);check('editable artwork saved only to its learner gallery',len(alpha['art'])==1 and len(page.evaluate('id=>BrightwakeStore.get(id)',b)['art'])==0)
 check('shape controls edit actual geometry',alpha['art'][0]['pieces'][0]['x']==388 and alpha['art'][0]['pieces'][0]['color']=='#284c60')
 page.screenshot(path=str(out/'brightwake-pumpkin-ipad.png'),full_page=True)
 page.locator('.learner-pill').click();page.locator(f'#modal [data-id="{b}"]').click();page.locator('[data-act="family"]').first.click();check('sibling cannot see first learner artwork in its gallery',page.locator('[data-gallery]').count()==0)
 page.locator('.learner-pill').click();page.locator(f'#modal [data-id="{a}"]').click();page.locator('[data-act="family"]').first.click();check('switching back restores own saved artwork',page.locator('[data-gallery]').count()==1)
 with page.expect_download() as d:page.locator('[data-act="export"]').click()
 export=out/'SYNTHETIC-learner.json';d.value.save_as(export);doc=json.loads(export.read_text())
 check('export includes only selected learner and warns unencrypted',doc['profile']['id']==a and 'Star Owl' not in export.read_text() and 'unencrypted' in doc['warning'])
 with page.expect_file_chooser() as fc:page.locator('[data-act="import"]').first.click()
 fc.value.set_files(export);page.wait_for_timeout(250);data=page.evaluate('BrightwakeStore.list()')
 check('import creates a new identity without overwriting originals',len(data)==3 and len(set(p['id'] for p in data))==3 and next(p for p in data if p['id']==b)==beta_before)
 check('imported history explicitly unverified','IMPORTED HISTORY' in page.locator('body').inner_text())
 bad=dict(doc);bad['profile']=dict(doc['profile']);bad['profile']['nickname']='x'*90;badfile=out/'invalid-learner.json';badfile.write_text(json.dumps(bad))
 with page.expect_file_chooser() as fc:page.locator('[data-act="import"]').first.click()
 fc.value.set_files(badfile);page.wait_for_timeout(120);check('malformed learner import is rejected',len(page.evaluate('BrightwakeStore.list()'))==3 and 'Import stopped' in page.locator('#toast').inner_text())
 page.locator('[data-act="home"]').first.click();page.locator('.activity-card[data-act="trails"]').click();canvas=page.locator('#trace-canvas');box=canvas.bounding_box();page.mouse.move(box['x']+box['width']*.4,box['y']+box['height']*.2);page.mouse.down();page.mouse.move(box['x']+box['width']*.5,box['y']+box['height']*.8,steps=15);page.mouse.up();page.locator('[data-act="trace-save"]').click();page.wait_for_timeout(100)
 copyid=next(p['id'] for p in data if p['id'] not in [a,b]);check('letter practice belongs only to active learner',page.evaluate('id=>BrightwakeStore.get(id)',copyid)['trails'].get('A')==1 and not page.evaluate('id=>BrightwakeStore.get(id)',a)['trails'])
 page.locator('[data-act="lowercase"]').click();check('lowercase guides are selectable',page.locator('#trace-canvas').get_attribute('aria-label').startswith('Trace the letter a'))
 page.screenshot(path=str(out/'brightwake-letters-ipad.png'),full_page=True)
 page.locator('[data-act="home"]').first.click();page.locator('[data-act="flight"]').click();page.locator('[data-act="flight-pause"]').click();page.wait_for_timeout(1100);check('touch-sailing activity starts without learning prerequisites',page.locator('[data-act="flight-pause"]').inner_text()=='Pause')
 page.locator('[data-act="flight-pause"]').click();check('player can pause without a penalty',page.locator('[data-act="flight-pause"]').inner_text()=='Resume sailing')
 page.screenshot(path=str(out/'brightwake-sailing-ipad.png'),full_page=True)
 page.locator('[data-act="home"]').first.click();page.locator('[data-act="map"]').first.click();page.locator('#grade-filter').select_option('12');page.locator('[data-skill="logarithm"]').click();prompt=page.locator('.question-title').inner_text();v=int(re.search(r'\((\d+)\)',prompt).group(1));answer=v.bit_length()-1;page.locator('#number-answer').fill(str(answer));page.locator('[data-act="check"]').click();page.wait_for_selector('[data-act="next"]');check('high-school sample is a functioning checked problem','Independent discovery' in page.locator('#feedback').inner_text())
 page.screenshot(path=str(out/'brightwake-highschool-ipad.png'),full_page=True)
 page.locator('[data-act="home"]').first.click();page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(400);check('phone home has no horizontal overflow',page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.screenshot(path=str(out/'brightwake-islands-phone.png'),full_page=True)
 page.locator('.activity-card[data-act="studio"]').click();page.locator('[data-theme="tree"]').click();page.locator('[data-shape="star"]').click();page.locator('[data-act="save-art"]').click();page.wait_for_timeout(100);check('phone creative editor has no horizontal overflow',page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.screenshot(path=str(out/'brightwake-tree-phone.png'),full_page=True)
 before=page.evaluate('id=>BrightwakeStore.get(id)',copyid);page.evaluate('fixtureWriteBlocked=true');page.locator('[data-shape="circle"]').click();page.locator('[data-act="save-art"]').click();page.wait_for_timeout(150)
 check('refused save is clearly visible, not falsely confirmed','Save not verified' in page.locator('#notice').inner_text())
 check('quota failure preserves previously saved profile',page.evaluate('id=>BrightwakeStore.get(id)',copyid)==before)
 page.locator('[data-act="family"]').first.click()
 with page.expect_download() as d:page.locator('[data-act="export"]').click()
 exp=out/'SYNTHETIC-unsaved-export.json';d.value.save_as(exp);u=json.loads(exp.read_text());check('unsaved in-memory creation can still be exported',len(u['profile']['art'][-1]['pieces'])==2)
 check('no fleet database was accessed',page.evaluate('fixtureOpened.every(n=>n==="blackflag.brightwake.learners.v1")'))
 check('no attempted outbound traffic',not network)
 check('no unhandled page exception',not errors)
 browser.close()
(out/'browser-results.json').write_text(json.dumps({'scope':__doc__,'checks':checks,'page_errors':errors,'network_attempts':network,'native_safari':'pending','native_indexeddb':'not available in restricted browser origin; explicit fixture used'},indent=2))
print(json.dumps({'passed':len(checks),'failed':sum(not c['pass'] for c in checks)}))
